%------------------------
% Northeastern CV Template
% Based on: COS Northeastern University Faculty CV
%------------------------

\documentclass[a4paper,9pt]{extarticle}

\usepackage[utf8]{inputenc}
\usepackage{geometry}
\geometry{a4paper, margin=1in}
\usepackage{titlesec}
\usepackage{enumitem}
\usepackage[hidelinks]{hyperref}
\usepackage{changepage}

\setlist{noitemsep}
\titleformat{\section}{\large\bfseries}{\thesection}{1em}{}[\titlerule]
\titlespacing*{\section}{0pt}{\baselineskip}{\baselineskip}

\newenvironment{subs}
  {\adjustwidth{2em}{0pt}}
  {\endadjustwidth}

\begin{document}

\pagestyle{empty}

%--- HEADER ---
\begin{center}
    \textbf{\Large {{escapeLaTeX basics.name}} }\\[3pt]
    \textbf{Curriculum Vitae}\\[1pt]
    {{#if basics.location.city}}{{escapeLaTeX basics.location.city}}{{/if}}{{#if basics.email}} $|$ \href{mailto:{{basics.email}} }{ {{escapeLaTeX basics.email}} }{{/if}}{{#if basics.url}} $|$ \href{ {{basics.url}} }{ {{escapeLaTeX basics.url}} }{{/if}}
    {{#if basics.profiles}}\\
    {{#each basics.profiles}}\href{ {{url}} }{ {{escapeLaTeX network}} }{{#unless @last}} $|$ {{/unless}}{{/each}}
    {{/if}}
\end{center}

{{#if basics.summary}}
\section*{PERFIL}
\noindent
{{escapeLaTeX basics.summary}}
{{/if}}

%--- SECTIONS (respects user-defined order) ---
{{#each _sectionOrder}}
{{#if (eq this "education")}}
{{#if (notEmpty @root.education)}}
\section*{EDUCACI\'{O}N}
{{#each @root.education}}
\noindent
\textbf{ {{escapeLaTeX studyType}} {{#if area}}en {{escapeLaTeX area}}{{/if}} } \\
{{formatDate startDate}}{{#if endDate}} -- {{formatDate endDate}}{{else}} -- Actualidad{{/if}} \\
\textit{ {{escapeLaTeX institution}} }
{{#if score}}\\Calificaci\'{o}n: {{escapeLaTeX score}}{{/if}}
{{#if (notEmpty courses)}}\\\textit{Cursos:} {{join courses ", "}}{{/if}}

\vspace{6pt}

{{/each}}
{{/if}}
{{else if (eq this "work")}}
{{#if (notEmpty @root.work)}}
\section*{EXPERIENCIA LABORAL}
{{#each @root.work}}
\noindent
\textbf{ {{escapeLaTeX position}} } \\
{{formatDate startDate}} -- {{#if endDate}}{{formatDate endDate}}{{else}}Actualidad{{/if}} \\
\textit{ {{escapeLaTeX name}} }{{#if location}}, {{escapeLaTeX location}}{{/if}}
{{#if summary}}\\ {{escapeLaTeX summary}}{{/if}}
{{#if (notEmpty highlights)}}
\begin{itemize}
{{#each highlights}}
  \item {{escapeLaTeX this}}
{{/each}}
\end{itemize}
{{/if}}

\vspace{6pt}

{{/each}}
{{/if}}
{{else if (eq this "publications")}}
{{#if (notEmpty @root.publications)}}
\section*{PUBLICACIONES}
{{#each @root.publications}}
\noindent
\textbf{ {{escapeLaTeX name}} }{{#if releaseDate}} [{{formatDate releaseDate}}]{{/if}} \\
{{#if publisher}}\textit{ {{escapeLaTeX publisher}} }\\{{/if}}
{{#if summary}}{{escapeLaTeX summary}}\\{{/if}}
\vspace{4pt}

{{/each}}
{{/if}}
{{else if (eq this "projects")}}
{{#if (notEmpty @root.projects)}}
\section*{ACTIVIDAD CREATIVA}
{{#each @root.projects}}
\noindent
\textbf{ {{escapeLaTeX name}} }{{#if startDate}} ({{formatDate startDate}}{{#if endDate}} -- {{formatDate endDate}}{{else}} -- Actualidad{{/if}}){{/if}} \\
{{#if description}}\textit{ {{escapeLaTeX description}} }\\{{/if}}
{{#if (notEmpty highlights)}}
\begin{itemize}
{{#each highlights}}
  \item {{escapeLaTeX this}}
{{/each}}
\end{itemize}
{{/if}}

\vspace{4pt}

{{/each}}
{{/if}}
{{else if (eq this "awards")}}
{{#if (notEmpty @root.awards)}}
\section*{BECAS Y PREMIOS}
\begin{subs}
{{#each @root.awards}}
\noindent
\textbf{ {{escapeLaTeX title}} }{{#if date}} [{{formatDate date}}]{{/if}} \\
{{#if awarder}}Otorgado por: \textit{ {{escapeLaTeX awarder}} }\\{{/if}}
{{#if summary}}{{escapeLaTeX summary}}\\{{/if}}
\vspace{4pt}

{{/each}}
\end{subs}
{{/if}}
{{else if (eq this "certificates")}}
{{#if (notEmpty @root.certificates)}}
\section*{CERTIFICADOS}
\begin{subs}
{{#each @root.certificates}}
\noindent
\textbf{ {{escapeLaTeX name}} }{{#if date}} [{{formatDate date}}]{{/if}} \\
{{#if issuer}}Emitido por: \textit{ {{escapeLaTeX issuer}} }\\{{/if}}
{{#if url}}\href{ {{url}} }{Ver certificado}\\{{/if}}
\vspace{4pt}

{{/each}}
\end{subs}
{{/if}}
{{else if (eq this "volunteer")}}
{{#if (notEmpty @root.volunteer)}}
\section*{SERVICIO Y VOLUNTARIADO}
{{#each @root.volunteer}}
\noindent
\textbf{ {{escapeLaTeX position}} } \\
{{formatDate startDate}} -- {{#if endDate}}{{formatDate endDate}}{{else}}Actualidad{{/if}} \\
\textit{ {{escapeLaTeX organization}} }
{{#if summary}}\\ {{escapeLaTeX summary}}{{/if}}
{{#if (notEmpty highlights)}}
\begin{itemize}
{{#each highlights}}
  \item {{escapeLaTeX this}}
{{/each}}
\end{itemize}
{{/if}}

\vspace{6pt}

{{/each}}
{{/if}}
{{else if (eq this "skills")}}
{{#if (notEmpty @root.skills)}}
\section*{HABILIDADES Y COMPETENCIAS}
\begin{subs}
{{#each @root.skills}}
\noindent
\textbf{ {{escapeLaTeX name}} }{{#if (notEmpty keywords)}}: {{join keywords ", "}}{{/if}} \\
{{/each}}
\end{subs}
{{/if}}
{{else if (eq this "languages")}}
{{#if (notEmpty @root.languages)}}
\section*{IDIOMAS}
\begin{subs}
{{#each @root.languages}}
\noindent
{{escapeLaTeX language}}{{#if fluency}} --- {{escapeLaTeX fluency}}{{/if}} \\
{{/each}}
\end{subs}
{{/if}}
{{else if (eq this "interests")}}
{{#if (notEmpty @root.interests)}}
\section*{INTERESES}
\begin{subs}
{{#each @root.interests}}
\noindent
\textbf{ {{escapeLaTeX name}} }{{#if (notEmpty keywords)}}: {{join keywords ", "}}{{/if}} \\
{{/each}}
\end{subs}
{{/if}}
{{else if (eq this "references")}}
{{#if (notEmpty @root.references)}}
\section*{REFERENCIAS}
{{#each @root.references}}
\noindent
\textbf{ {{escapeLaTeX name}} } \\
{{escapeLaTeX reference}}

\vspace{6pt}

{{/each}}
{{/if}}
{{/if}}
{{/each}}

\end{document}
